  assignments text;
begin
  select string_agg(format('%I = excluded.%I', column_name, column_name), ', ' order by ordinal_position)
    into assignments
    from information_schema.columns
   where table_schema = 'public'
     and table_name = 'team_schedule_events'
     and column_name <> 'id'
     and is_generated = 'NEVER';
  execute format(
    'insert into public.team_schedule_events select * from jsonb_populate_recordset(null::public.team_schedule_events, $1) on conflict (id) do update set %s',
    assignments
  ) using payload;
  if (select count(*) from public.team_schedule_events where id in (select (item->>'id')::uuid from jsonb_array_elements(payload) item)) <> jsonb_array_length(payload) then
    raise exception 'Competition date sync verification failed';
  end if;
